 'functions',coalesce((select jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'security_definer',p.prosecdef,'configuration',p.proconfig,'definition',pg_get_functiondef(p.oid)) order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('ads_reporting_transition','ads_lead_counts','ads_csv_commit','ads_csv_lead_counts')),'[]'::jsonb),
 'table_grants',coalesce((select jsonb_agg(jsonb_build_object('table',table_name,'role',grantee,'privilege',privilege_type) order by table_name,grantee,privilege_type) from information_schema.table_privileges where table_schema='public' and table_name in ('ads_reporting_state','ads_lead_review','ads_csv_accounts','ads_csv_access','ads_csv_rows','ads_csv_imports')),'[]'::jsonb),
 'function_grants',coalesce((select jsonb_agg(jsonb_build_object('function',routine_name,'role',grantee,'privilege',privilege_type) order by routine_name,grantee) from information_schema.routine_privileges where routine_schema='public' and routine_name in ('ads_reporting_transition','ads_lead_counts','ads_csv_commit','ads_csv_lead_counts')),'[]'::jsonb)
